  assert.equal(d.querySelector('#backupScopeDescription').hidden,true);assert.equal(d.querySelector('#backupScopeCounts').hidden,true);
  assert.equal(d.querySelector('#importDataButton').textContent,'导入备份文件');assert.equal(d.querySelector('#importDataButton i'),null);assert.equal(d.querySelector('.backup-restore-section>header'),null);assert.equal(d.querySelector('.backup-restore-section>p'),null);
  let captured=null,download='';f.w.IrisBackup.make=async(data,scope,categories)=>{captured={data,scope,categories};return{data,manifest:{counts:{localBlobRefs:0}}}};f.w.URL.createObjectURL=()=> 'blob:export-fixture';f.w.URL.revokeObjectURL=()=>{};f.w.HTMLAnchorElement.prototype.click=function(){download=this.download};
  let pending=f.w.exportData();assert.ok(d.querySelector('.ng-export-dialog[open]'));assert.deepEqual(Array.from(d.querySelectorAll('.ng-export-categories li'),node=>node.textContent),['用户资料']);assert.equal(d.querySelector('.ng-export-counts dd').textContent,'1');assert.equal(captured,null);
  d.querySelector('.ng-export-dialog footer button').click();await pending;assert.equal(captured,null);assert.equal(download,'');assert.equal(d.querySelector('#exportData').disabled,false);
  pending=f.w.exportData();f.w.eval("state.users[0].name='确认期间的修改';backupExportFormat='zip';backupExportCategories=['onlineChat']");d.querySelector('[data-export-confirm]').click();await pending;
