  page('more','interaction');const life=d.querySelector('[data-life-enabled]');assert.ok(life);life.checked=false;life.dispatchEvent(new f.w.Event('change',{bubbles:true}));assert.equal(d.querySelector('[data-online-settings-page="followups"]').hidden,true);life.checked=true;life.dispatchEvent(new f.w.Event('change',{bubbles:true}));d.querySelector('[data-online-settings-page="followups"]').click();assert.equal(d.querySelector('#closeSettings').textContent,'记挂的事情');assert.ok(d.querySelector('.life-followup-list'));assert.equal(d.querySelector('.life-followup-disclosure>summary'),null);d.querySelector('#closeSettings').click();assert.equal(d.querySelector('#closeSettings').textContent,'角色互动');assert.ok(d.querySelector('[data-online-settings-page="followups"]'));
